using System;
using System.Collections;
using Astrea.BattleActions;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AphoticInstinctEffect", menuName = "Data/Battle/Effects/Enemy/AphoticInstinct Effect")]
public class AphoticInstinctEffect : Effect
{
	[SerializeField]
	private DefaultEffectAction doomAction;

	[SerializeField]
	private Effect doomEffect;

	[Header("Gaining Doom")]
	[SerializeField]
	private float delayBeforeAnimation;

	[SerializeField]
	private float delayToScreenShake;

	[SerializeField]
	private float delayToVFX;

	[SerializeField]
	private FloatFloatEvent OnScreenShake;

	[SerializeField]
	private float shakePower = 0.1f;

	[SerializeField]
	private float shakeDuration = 0.3f;

	[SerializeField]
	private float delayBetweenDoomAndAphoticInstinct;

	[SerializeField]
	private float delayAfterAnimation;

	[SerializeField]
	private int[] doomPerTurnAmount;

	[Header("Losing Doom")]
	[SerializeField]
	private float delayToLosingAllDoomSFX;

	[NonSerialized]
	private int startingDoomAmount;

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		string text = "";
		if (GameScenesUtils.IsBattleScene())
		{
			if ((bool)effectOwner.GetComponent<CorruptedAnimalEffects>() && effectOwner.GetComponent<CorruptedAnimalEffects>().IsDeclineActiveGetAmount() > 1)
			{
				text = "\n" + Smart.Format(base.localizationManager.GetLocalizedString("NextTurnDoom"), amount);
			}
		}
		else
		{
			text = "\n" + Smart.Format(base.localizationManager.GetLocalizedString("NextTurnDoom"), "X");
		}
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedAtTheEndOfItsTurn(), startingDoomAmount + GetCurrentDifficultyLevelDoomPerTurnAmount(), GetCurrentDifficultyLevelDoomPerTurnAmount(), text);
	}

	private int GetCurrentDifficultyLevelDoomPerTurnAmount()
	{
		int currentDifficultyLevelModifyEnemiesHighestIndex = ReferenceSingleton<AssetsReference>.Instance.DifficultyLevels.GetCurrentDifficultyLevelModifyEnemiesHighestIndex();
		if (doomPerTurnAmount.Length > currentDifficultyLevelModifyEnemiesHighestIndex)
		{
			return doomPerTurnAmount[currentDifficultyLevelModifyEnemiesHighestIndex];
		}
		return doomPerTurnAmount[doomPerTurnAmount.Length - 1];
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		startingDoomAmount = effectAmount;
		ReferenceSingleton<CoroutineHandler>.Instance.Run(ResetDoomCoroutine(effectOwner, effectAmount));
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.SetAphoticInstinctAction(ResetDoomCoroutine(effectOwner, effectAmount));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		return effectAmount;
	}

	private IEnumerator ResetDoomCoroutine(GameObject effectOwner, int effectAmount)
	{
		yield return new WaitForSeconds(delayBeforeAnimation);
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToVFX, delegate
		{
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 5f);
		});
		PlayEffectActivationSFX();
		UnitEffects unitEffects = effectOwner.GetComponent<UnitEffects>();
		PlayAnimation(unitEffects, "Skill", AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
		{
			unitEffects.GetComponent<SpriteControl>().PlayAnimation(AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
		});
		yield return new WaitForSeconds(delayToScreenShake);
		int num = unitEffects.IsEffectActiveGetAmount(doomEffect, activateFeedback: false);
		doomAction.CastTargetAmount(effectOwner, effectAmount - num, null);
		OnScreenShake.Raise(shakePower, shakeDuration);
		if (effectOwner.GetComponent<CorruptedAnimalEffects>().IsDeclineActiveGetAmount() == 2)
		{
			unitEffects.DecreaseEffect(unitEffects.IsEffectActiveGetEffectInstance(this), effectAmount + 2, activateFeedback: false, removeOnZero: false);
		}
		else
		{
			yield return new WaitForSeconds(delayBetweenDoomAndAphoticInstinct);
			unitEffects.AddEffect(this, GetCurrentDifficultyLevelDoomPerTurnAmount());
		}
		yield return new WaitForSeconds(delayAfterAnimation);
	}

	public void DecreaseDoom(UnitEffects unitEffects, int amount)
	{
		if (unitEffects.IsEffectActiveGetAmount(doomEffect, activateFeedback: false) <= 0)
		{
			return;
		}
		unitEffects.DecreaseEffect(doomEffect, amount);
		SpriteControl component = unitEffects.GetComponent<SpriteControl>();
		float trackTime = component.GetCurrentTrackEntry().TrackTime;
		PlayAnimation(unitEffects, "Idle", AnimationChangeType.StayInTheNewAnimationLooping, null);
		component.GetCurrentTrackEntry().TrackTime = trackTime;
		if (unitEffects.IsEffectActiveGetAmount(doomEffect, activateFeedback: false) == 0)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToLosingAllDoomSFX, delegate
			{
				PlaySecondEffectActivationSFX();
			});
		}
	}

	private void PlayAnimation(UnitEffects unitEffects, string animationTypePrefix, AnimationChangeType animationChangeType, Action afterAnimationAction)
	{
		AnimationType animationType = GetAnimationType(unitEffects, animationTypePrefix);
		unitEffects.GetComponent<SpriteControl>().PlayAnimationForcedIfSpecificAnimationIsNotPlaying(animationType, animationType, animationChangeType, afterAnimationAction);
	}

	public AnimationType GetAnimationType(UnitEffects unitEffects, string animationTypePrefix)
	{
		float num = (float)unitEffects.IsEffectActiveGetAmount(doomEffect, activateFeedback: false) / (float)startingDoomAmount;
		if (num > 0.33f && num <= 0.66f)
		{
			animationTypePrefix += "1";
		}
		else if (num > 0f && num <= 0.33f)
		{
			animationTypePrefix += "2";
		}
		else if (num == 0f)
		{
			animationTypePrefix += "3";
		}
		Enum.TryParse<AnimationType>(animationTypePrefix, out var result);
		return result;
	}
}
